import type { Features_2_Block } from "~/payload-types";
import { Icon } from "@/registry/ui/icon";

export * from "./config";

export default function Features(props: NonNullable<Features_2_Block>) {
	return (
		<section className="py-12 md:py-20">
			<div className="mx-auto max-w-5xl space-y-8 px-6 md:space-y-16">
				<div className="relative z-10 mx-auto max-w-xl space-y-6 text-center md:space-y-12">
					<h2 className="text-4xl font-medium text-balance lg:text-5xl">
						{props.header ?? ""}
					</h2>
					<p>{props.subheader ?? ""}</p>
				</div>

				<div className="relative mx-auto grid max-w-4xl divide-x divide-y rounded-md border *:p-12 sm:grid-cols-2 lg:grid-cols-3">
					{(props.features ?? []).map((feature, index) => (
						<div className="space-y-2" key={`feature-${index}`}>
							<div className="flex items-center gap-2">
								<Icon icon={feature.icon} />
								<h3 className="text-sm font-medium">{feature.header}</h3>
							</div>
							<p className="text-sm">{feature.description}</p>
						</div>
					))}
				</div>
			</div>
		</section>
	);
}

import type { Block } from "payload";
import {
	BLOCK_GROUP_FEATURES,
	BLOCK_SLUG_FEATURES_2,
} from "@/registry/default/lib/constants/blocks";
import descriptionField from "@/registry/default/lib/fields/description/config";
import headerField from "@/registry/default/lib/fields/header/config";
import iconField from "@/registry/default/lib/fields/icon/config";
import subHeaderField from "@/registry/default/lib/fields/subheader/config";

export const Features_2_Block: Block = {
	slug: BLOCK_SLUG_FEATURES_2,
	interfaceName: "Features_2_Block",
	labels: {
		singular: "Features 2",
		plural: "Features 2's",
	},
	admin: {
		group: BLOCK_GROUP_FEATURES,
	},
	fields: [
		headerField({
			required: false,
			defaultValue: "Everything You Need to Ship Fast",
		}),
		subHeaderField({
			required: false,
			defaultValue:
				"Professional blocks, templates, and hosting solutions. Build stunning marketing sites with no-code ease, or customize everything with full developer control.",
		}),
		{
			name: "features",
			type: "array",
			fields: [
				iconField({
					required: true,
				}),
				headerField(),
				descriptionField({ required: true }),
			],
			defaultValue: [
				{
					icon: "Blocks",
					header: "50+ PayloadCMS Blocks",
					description: "Production-ready components for any marketing site",
				},
				{
					icon: "Zap",
					header: "One-Click Deploy",
					description: "Deploy to AWS with SST in minutes, not hours",
				},
				{
					icon: "Palette",
					header: "Full Customization",
					description: "Tailwind + shadcn/ui with your design system",
				},
				{
					icon: "Smartphone",
					header: "Mobile-First Design",
					description: "Responsive blocks that work perfectly on all devices",
				},
				{
					icon: "Shield",
					header: "Enterprise Auth",
					description: "Better-auth integration with role-based access",
				},
				{
					icon: "Rocket",
					header: "Managed Hosting",
					description: "Zero-config hosting for non-technical founders",
				},
			],
		},
	],
};
